INSERT INTO `advances` (`id`, `awesome`, `h`, `p`, `sort`) VALUES(1, 'fa-check-square', 'Экономия времени!', 'Люди очень ценят своё время, поэтому им удобно оценить Ваши преимущества не выходя из дома (с компьютера или даже из автомобиля через мобильные устройства)', 0);
INSERT INTO `advances` (`id`, `awesome`, `h`, `p`, `sort`) VALUES(2, 'fa-check-square', 'Реклама 24 часа в сутки!', 'Виртуальный тур рекламирует Вас круглые сутки. Ваши клиенты могут в любую минуту дня или ночи посетить и оценить Ваш объект', 0);
INSERT INTO `advances` (`id`, `awesome`, `h`, `p`, `sort`) VALUES(3, 'fa-check-square', 'Наглядность!', 'Виртуальный тур позволяет очень наглядно продемонстрировать Ваш объект, и выделить Вас среди конкурентов', 0);
INSERT INTO `advances` (`id`, `awesome`, `h`, `p`, `sort`) VALUES(4, 'fa-check-square', 'Комплексный подход!', 'Наша компания предлагает Вам полный комплекс услуг от создания виртуального тура до создания сайта для размещения виртуального тура', 0);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(1, 'Возможность размещения информации в виртуальном туре', '', 'Часто клиенты интересуются, как можно разнообразить виртуальный тур дополнительными материалами и что туда можно вставить. Вставляются картинки, фотографии и видеоролики. Они могут быть интегрированы в текстуру и представлять собой, например, замену изобр', 0, 'Возможность размещения информации в виртуальном туре', 'vozmojnost-razmescheniya-informatsii-v-virtualnom-ture', 'Часто клиенты интересуются, как можно разнообразить виртуальный тур дополнительными материалами и что туда можно вставить.\nДавайте разберемся подробнее.', '<p style=\"text-align:justify\"><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/1/1_170126151744_.jpeg\" style=\"float:left; height:169px; margin-left:5px; margin-right:5px; width:300px\" />Часто клиенты интересуются, как можно разнообразить виртуальный тур дополнительными материалами и что туда можно вставить. Давайте разберемся подробнее.</p>\n\n<p style=\"text-align:justify\">Для начала расскажем о способах представления информации в виртуальном туре:</p>\n\n<ul>\n	<li style=\"text-align:justify\">Элемент непосредственно виден при просмотре и расположен &laquo;поверх&raquo; картинки. Таким способом вставляются картинки, фотографии и видеоролики. Они могут быть интегрированы в текстуру и представлять собой, например, замену изображения на телеэкране или картины в рамке.</li>\n	<li style=\"text-align:justify\">Элемент появляется только при нажатии на определенную область виртуального тура. Выглядит как и в вышеописанном случае, но при нажатии кнопкой мыши, элемент будет масштабироваться на весь экран, либо до заданного фиксированного размера. Это дает возможность более подробно ознакомиться с дополнительной информацией.</li>\n	<li style=\"text-align:justify\">Элемент вызывается на экран нажатием на кнопку-иконку. В виртуальный тур, в определенные места вставляются кнопки, обозначающие фотографии, текстовую информацию или видео. При нажатии на такую кнопку появляется элемент. Следует учесть, что в этом случае размер изображения фиксирован, масштабирование невозможно.</li>\n	<li style=\"text-align:justify\">Элемент является ссылкой. В этом варианте можно разместить в окне виртуального тура любую графическую кнопку. При наведении курсора появится всплывающая подсказка, а при щелчке мышью, будет осуществлен переход на указанную страницу. Так обычно вставляется логотип заказчика в тур. При нажатии на него осуществляется переход на указанный веб-сайт.</li>\n</ul>\n\n<p style=\"text-align:justify\">Теперь несколько слов о самих дополнительных элементах:</p>\n\n<ul>\n	<li style=\"text-align:justify\">Текст. Его в туре может быть сколько угодно. В виде названий элементов, узлов, обозначений. В виде всплывающих подсказок и постоянно видимый. Можно разместить блок текста-описания с возможностью прокрутки в небольшом окне внутри тура.</li>\n	<li style=\"text-align:justify\">Изображение (фотография). Вставка дополнительных изображений позволяет сфокусировать пользователя на конкретном элементе, показать его преимущества более детально.</li>\n	<li style=\"text-align:justify\">Звук. Виртуальный тур можно дополнить фоновым звуком. На каждую панораму своя аудиодорожка, либо звук будет слышно только в определенном месте при просмотре тура. Тут главное знать чувство меры, чтобы не раздражать клиента навязчивым звуком и предусмотреть кнопки, отключающие и регулирующие громкость.</li>\n	<li style=\"text-align:justify\">Видео. Да, в виртуальном 3D-туре можно разместить любое видео. Оно может быть интегрировано в сам тур, а может подгружаться с любого известного видеохостинга, например, с youtube. Размер, качество и способ управления видеороликом можно варьировать, как и способ начала воспроизведения (авто, вручную).</li>\n</ul>\n', '2017-01-24 21:00:00', '2018-10-31 12:37:28', 2, 0, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(3, '', '', '', NULL, 'Тестовая', 'testovaya', 'Краткое описание', '<p>Полное описание</p>\n', '2017-01-31 17:00:00', '2017-02-01 16:54:22', 2, 1, 0);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(4, 'зачем нам виртуальный тур', '', 'Зачем нам виртуальный тур? Создание виртуального тура дает возможность более презентабельно, с выгодной для Вас стороны показать Ваш бизнес и позволить клиенту продолжительное время оставаться на вашем сайте чтобы детально рассмотреть все интересующие его', NULL, 'Зачем нужен виртуальный тур', 'zachem-nujen-virtualnyiy-tur', 'Периодически приходится отвечать на вопрос \"А зачем нам виртуальный тур?\"\nДавайте разберемся вместе.', '<p style=\"text-align:justify\"><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/4/4_170201165622_.jpeg\" style=\"float:left; height:175px; margin-left:5px; margin-right:5px; width:300px\" />В большинстве случаев на сайте компании существует раздел &quot;Фотогалерея&quot;, в котором клиенты могут посмотреть и оценить интерьер Вашей компании. Особенно это интересно для гостиниц, ресторанов, баров, спортивных центров.</p>\n\n<p style=\"text-align:justify\">А что мы видим когда попадаем в такой раздел? Зачастую там представлены фотографии общего вида помещения, сделанные на смартфон или обычную цифровую фотокамеру. Качество таких фотографии оставляет желать лучшего, а просмотр у клиента не займет много времени и не оставит в памяти &laquo;отклик&raquo; о Вас.</p>\n\n<p style=\"text-align:justify\">Создание виртуального тура в таком случае дает возможность более презентабельно, с выгодной для Вас стороны показать Ваш бизнес и позволит клиенту продолжительное время оставаться на вашем сайте чтобы детально рассмотреть все интересующие его нюансы (например, состояние мебели, модели оборудования, комфортность интерьеров).</p>\n\n<p style=\"text-align:justify\">В любой виртуальный тур можно вставлять фотографии отдельных элементов или даже видеоролики, демонстрирующие какие-либо особенности или текстовые комментарии. Это добавляет интерактивности, увлекает клиента.</p>\n\n<p style=\"text-align:justify\">Кроме того, практика показывает, что клиент, посмотревший виртуальный тур, зайдет на ваш сайт снова и как минимум покажет его своему знакомому. А это задействует один из самых эффективных информационных каналов &ndash; сарафанное радио.</p>\n', '2017-01-30 21:00:00', '2018-10-31 12:34:54', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(5, 'Подготовка интерьера к съемке виртуального тура', '', 'Статья о том, как подготовить ваше помещение к съемке виртуального тура. Виртуальный 3D-тур помогает показать интерьер клиенту с выгодной для Вас стороны, подчеркивая детали. Позаботьтесь о том, чтобы Ваш интерьер выглядел безупречно и поток клиентов Вам ', NULL, 'Подготовка интерьера к съемке', 'podgotovka-interera-k-syemke', 'Заметки по подготовке интерьера к съемке для виртуального тура', '<p style=\"text-align:justify\"><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/5/5_170201180317_.jpeg\" style=\"float:left; height:188px; margin-left:5px; margin-right:5px; width:300px\" />Очень часто, во время съемок приходится слышать от владельца заведения такие просьбы: &laquo;&hellip;ну ты ж потом в фотошопе можешь вот это убрать&raquo;, &laquo;&hellip; вот эту тряпку замажь потом в программе&raquo;, &laquo;..ты там потом пол почисти от грязи&raquo;, &laquo;&hellip;тут фон замени&raquo;, &laquo;&hellip;дорисуй потом&raquo; и еще много подобных пожеланий.<br />\n<br />\nДа, конечно, на этапе редактирования и сборки панорам в единый виртуальный тур можно вносить любые коррективы, НО, во-первых, это требует значительных временных затрат, и как следствие повышает стоимость заказа, а во-вторых глубокая ретушь в некоторых случаях приводит к тому, что интерьер теряет свою &laquo;натуральность&raquo;, и становится &laquo;нарисованным&raquo;, не естественным.<br />\n<br />\nЧтобы избежать таких проблем, настоятельно рекомендую всем клиентам по возможности подготавливать помещения для съемки. Что необходимо знать и сделать:&nbsp;<br />\n1. Сделать уборку помещения: вымыть полы, протереть пыль, вымыть стекла и зеркала.&nbsp;<br />\n2. Заменить перегоревшие лампы всех светильников.&nbsp;<br />\n3. Расставить мебель и аксессуары по местам.&nbsp;<br />\n4. На время съемки обеспечить статическое положение всех вещей: не перемещать мебель, не открывать двери, не включать/выключать свет (съемка одной точки панорамы заминает не более 5 минут).&nbsp;<br />\n5. Ограничить доступ персонала и клиентов в помещение съемки.&nbsp;<br />\n6. Оценить &laquo;взглядом хозяина&raquo; готовность помещения.&nbsp;<br />\n<br />\nВиртуальный 3D-тур помогает показать интерьер клиенту с выгодной для Вас стороны, подчеркивая детали.&nbsp;<br />\n<br />\nПозаботьтесь о том, чтобы Ваш интерьер выглядел безупречно и поток клиентов Вам обеспечен!</p>\n', '2017-01-31 21:00:00', '2018-10-31 12:32:03', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(6, 'Сколько стоит виртуальный тур', 'цена, стоимость, виртуальный, тур, обоснование, дорого, зачем, реклама, затраты, оплата, выгода', 'Хотите получить экономическое обоснования стоимости виртуального тура? Почитайте данную статью и у вас не останется сомнений, чтобы заказать виртуальный тур у нас.', NULL, 'Экономическое обоснования стоимости виртуального тура', 'ekonomicheskoe-obosnovaniya-stoimosti-virtualnogo-tura', 'Самый частый вопрос, который приходится слышать в ответ на коммерческое предложение о создании виртуального 3D-тура – какая цена услуги?\nХочу поделиться своими мыслями по этому поводу.', '<div style=\"text-align:justify\"><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/6/6_170329223320_.jpeg\" style=\"float:left; height:212px; margin:10px 20px 0 0; width:300px\" />Самый частый вопрос, который приходится слышать в ответ на коммерческое предложение о создании виртуального 3D-тура &ndash; какая цена услуги?</div>\n\n<div style=\"text-align:justify\">Хочу поделиться своими мыслями по этому поводу.</div>\n\n<div style=\"text-align:justify\">&nbsp;</div>\n\n<div style=\"text-align:justify\">Да, конечно, с точки зрения клиента, вопрос о стоимости стоит на первом месте. Это нормально. Каждый предприниматель (директор, управляющий) должен ориентироваться, может он это себе позволить или нет. Но есть множество моментов, о которых следует помнить.</div>\n\n<div style=\"text-align:justify\">Давайте разберемся подробнее на одном простом примере.</div>\n\n<div style=\"text-align:justify\">&nbsp;</div>\n\n<div style=\"text-align:justify\">Представьте себя на месте руководителя детского центра (частного садика), куда заботливые родители хотят отдать своего ребенка на полный день. Что их будет интересовать кроме стоимости? Да все просто: где будет находиться ребенок, какими игрушками играть, где и как дети кушают, как готовят пищу, как выглядит санузел, на чем они спят, &hellip;. и еще множество бытовых вопросов.</div>\n\n<div style=\"text-align:justify\">Не каждый родитель хочет тратить свое рабочее время на то, чтобы обойти несколько заведений и осмотреть их. Не каждый руководитель хочет, чтобы посторонние люди ходили по его заведению и осматривали все углы, задавая кучу неудобных вопросов и отнимали у него драгоценное время.</div>\n\n<div style=\"text-align:justify\">&nbsp;</div>\n\n<div style=\"text-align:justify\">Размещение виртуального тура на сайте заведения или в группе соц.сети в этом случае как раз и решает все эти вопросы. А доступность тура 24 часа в сутки позволяет показать интерьер в любой момент, не тратя время на другие, важные задачи.</div>\n\n<div style=\"text-align:justify\">&nbsp;</div>\n\n<div style=\"text-align:justify\">Выводы:</div>\n\n<div style=\"text-align:justify\">- виртуальный тур позволит потенциальным клиентам абсолютно в любой момент виртуально &laquo;посетить&raquo; Ваш детский центр,</div>\n\n<div style=\"text-align:justify\">- покажет с выгодной для Вас стороны все нюансы интерьеров,</div>\n\n<div style=\"text-align:justify\">- отфильтрует еще на этапе просмотра тура ту часть клиентов, которые и так в последующем не пришли бы к Вам,</div>\n\n<div style=\"text-align:justify\">- высвободит Вам дополнительное свободное время,</div>\n\n<div style=\"text-align:justify\">- выгодно выделит Вас среди конкурентов,</div>\n\n<div style=\"text-align:justify\">- упрочит имидж Вашего центра.</div>\n\n<div style=\"text-align:justify\">&nbsp;</div>\n\n<div style=\"text-align:justify\">Так сколько в итоге Вы готовы заплатить за такие конкурентные преимущества и лояльность клиентов?</div>\n\n<div style=\"text-align:justify\">&nbsp;</div>\n\n<div style=\"text-align:justify\">Чтобы не углубляться в сложные математические расчеты, отмечу ,что как показывает наша практика, итоговая стоимость создания виртуального 3D-тура для детского центра (частного детского сада) не будет превышать месячной стоимость посещения одним!!! Ребенком Вашего центра. По-вашему это дорого?</div>\n\n<div style=\"text-align:justify\">&nbsp;</div>\n\n<div style=\"text-align:justify\">И еще, в отличие от затрат на рекламу, где бюджет рассчитан на определенное время (количество показов), виртуальный 3D-тур оплачивается один раз и затем навсегда остается у Вас на сайте и в группах социальных сетей. Такая своеобразная &laquo;вечная&raquo; реклама с эффектом сарафанного радио и высоким коэффициентом запоминаемости.</div>\n', '2017-03-27 21:00:00', '2018-10-31 12:30:12', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(7, 'Photoshop в виртуальном туре', '', 'С помощью Photoshop мы можем исправить нежелательные детали вашего помещения в виртуальном туре. Кому-то не хочется показывать царапины на полу, кто-то хочет спрятать трещину на стене, а кто-то и вовсе желает, чтобы мы отфотошопили или дорисовали часть из', NULL, 'Photoshop в виртуальном туре', 'photoshop-v-virtualnom-ture', 'Маленькие секреты создания виртуального тура. Возможности ретуши изображений.', '<p><span style=\"font-size:13px\"><span style=\"font-family:-apple-system,BlinkMacSystemFont,Roboto,\"><span style=\"background-color:#ffffff\"><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/7/7_170331004521_.jpeg\" style=\"float:left; height:166px; margin:10px 20px 0 0; width:300px\" /></span></span></span></p>\n\n<div style=\"text-align:justify\">\n<p style=\"text-align:left\"><span style=\"font-size:16px\">Довольно часто при создании виртуального тура заказчик просит что-то отретушировать. Кому-то не хочется показывать царапины на полу, кто-то хочет спрятать трещину на стене, а кто-то и вовсе желает, чтобы мы отфотошопили или дорисовали часть изображения. Мы конечно против таких искусственных доделок и пытаемся оговаривать это с клиентом, но иногда все-таки приходится заниматься и такой работой.<br />\n<br />\nВот некоторые примеры исправлений.</span></p>\n\n<p style=\"text-align:left\"><span style=\"font-size:16px\">1. Изображение с телевизором. Во время съемки по ТВ шла реклама и ее хорошо было заметно в готовом туре. В результате было решено заменить рекламу на картинку информации из виртуального тура. Это одна из самых легких задач, которые приходится иногда решать.</span></p>\n\n<p style=\"text-align:center\"><span style=\"font-size:16px\"><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/7/tv.jpg\" style=\"height:341px; margin-bottom:20px; margin-top:20px\" /><br />\n<span style=\"background-color:#ffffff\">2. Батарея. На исходном изображении отсутствовал защитный экран у левого радиатора отопления. Чтобы не портить эстетический вид, в качестве донора был взят защитный экран от правого радиатора и дублирован на левую сторону. </span></span></p>\n\n<p style=\"text-align:center\"><span style=\"font-size:16px\"><span style=\"background-color:#ffffff\"><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/7/bat.jpg\" style=\"height:131px; margin-bottom:20px; margin-top:20px; width:600px\" /></span><br />\n<span style=\"background-color:#ffffff\">3. Дверь. Самый интересный пример &laquo;дорисовывания&raquo; картинки. Для изготовления виртуального тура по двухэтажному зданию было решено отснять коридор только второго этажа и так как коридоры первого и второго этажей одинаковые, то просто продублировать его еще и вниз. Но на этапе сборки виртуального тура поняли, что на первом этаже вместо окна &ndash; вход в здание. В запасе была отдельная фотография входа, которую и вставили вместо окна. На изображении ниже показана исходная и готовая картинка.</span></span></p>\n\n<p style=\"text-align:center\"><span style=\"font-size:16px\"><span style=\"background-color:#ffffff\"><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/7/door.jpg\" style=\"height:275px; margin-bottom:20px; margin-top:20px; width:600px\" /> </span><br />\n<span style=\"background-color:#ffffff\">Конечно, для виртуального тура можно и полностью нарисовать требуемую картинку, но основная идея &ndash; показать интерьер таким, какой он есть на самом деле, достоверным. </span></span></p>\n</div>\n', '2017-03-29 21:00:00', '2018-10-31 12:26:16', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(8, 'Разница между традиционной рекламой и виртуальным 3D-туром', 'реклама, разница, виртуальный, тур, традиционная, 3D, печатная, виртуальная, фотография, панорама', 'Думаете как запустить эффективную рекламу? Заказывайте виртуальный тур у нас, и мы разместим его на любой интернет-площадке: собственный сайт, социальные сети, ссылки на сторонних ресурсах, Google сервис, Yandex сервис.', NULL, 'Разница между традиционной рекламой и виртуальным 3D-туром', 'raznitsa-mejdu-traditsionnoy-reklamoy-i-virtualnyim-3d-turom', 'Сегодня обсудим разницу между традиционной рекламой и виртуальным 3D-туром', '<p><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/8/8_170810223358_.jpeg\" style=\"float:left; height:167px; width:300px\" />Обычная реклама (печатная/баннерная/аудио) создается на один раз, на одну рекламную кампанию. Показывается/транслируется в течении ограниченного времени, либо имеет определенное количество выходов. При этом стоимость создания готового материала зачастую дороже либо сопоставима со стоимостью создания виртуального тура.</p>\n\n<p>Виртуальный 3D-тур после создания можно демонстрировать неограниченное количество времени, он доступен 24 часа в сутки и может быть размещен на любой интернет-площадке (собственный сайт/социальные сети/ссылки на сторонних ресурсах). Плата за размещение в этом случае отсутствует, достаточно оплатить только создание материала.</p>\n\n<p>---</p>\n\n<p>Для создания макета печатной рекламы требуются услуги фотографа, ретушера, дизайнера, печатника. Оборудование, материалы и рекламные поверхности.</p>\n\n<p>Для создания готового виртуального тура достаточно только работы фотографа, в итоге клиент получает готовый виртуальный тур, размещенный на его сайте/в его группах в соц.сетях.</p>\n\n<p>---</p>\n\n<p>При размещении традиционной рекламы, целевая аудитория либо сильно ограничена возможностями рекламного канала, либо &laquo;стреляет&raquo; во все стороны, не учитывая интересы аудитории.</p>\n\n<p>Размещение виртуального тура на целевых ресурсах позволяет сфокусировать внимание целевой аудитории именно на представленном материале.</p>\n\n<p>&nbsp;</p>\n\n<p>Подводя итог вышенаписанному, стоить отметить, не совсем корректно сравнивать рекламу и виртуальный тур, потому как это разные подходы к тому, чтобы заявить о себе и продемонстрировать свои преимущества.</p>\n', '2017-08-08 21:00:00', '2018-10-31 12:22:45', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(9, 'Виртуальный 3D-тур Google', 'Google. street, view, virtual, tour, виртуальный, тур, особенности, преимущества', 'Мы прошли сертификацию в Google по программе Google Street View и теперь можем разместить Ваш виртуальный тур в сервисах Google.', NULL, 'Виртуальный 3D-тур Google', 'virtualnyiy-3d-tur-google', 'Преимущества размещения виртуального тура в Google', '<p><img alt=\"\" src=\"https://www.3dtur24.ru/public/articles/9/9_180122002215_.jpeg\" style=\"float:left; height:166px; margin:10px; width:300px\" />Мы прошли сертификацию в Google по программе Google Street View и теперь можем разместить Ваш виртуальный тур в самых популярных сервисах Google:</p>\n\n<p>- поисковая система Google;</p>\n\n<p>- Google.Карты;</p>\n\n<p>- Google.Просмотр улиц;</p>\n\n<p>- Google. Мой бизнес;</p>\n\n<p>- Google+.</p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p style=\"text-align:center\"><strong>Пример. Виртуальный тур Google для Дома мебели РИТАС</strong></p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<iframe src=\"https://www.google.com/maps/embed?pb=!4v1641978536884!6m8!1m7!1sCAoSLEFGMVFpcE1oV3NPYkZJbjJPWmN3N0dDRUZ4VmtLV0RxOFk4WmROV1N6cUZ5!2m2!1d56.02029554!2d93.00128595!3f330.4122695874763!4f0.3582446620156645!5f0.7820865974627469\" width=100% height=\"550\" style=\"border:0;\" allowfullscreen=\"\" loading=\"lazy\"></iframe>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p style=\"text-align:center\"><strong>Преимущества размещения виртуального тура в Google</strong></p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p>- Ваш виртуальный тур будет доступен сразу в нескольких сервисах Google.</p>\n\n<p>- Круглосуточный доступ к виртуальному туру.</p>\n\n<p>- Размещение круговых панорам &ndash; бесплатное.</p>\n\n<p>- Организации, имеющие виртуальный тур, лучше и выше индексируются в поисковой выдаче.</p>\n\n<p>- Карточка организации показывается на первой странице в поиске Google.</p>\n\n<p>- Размещение панорам с возможностью обновления виртуального тура в любое время.</p>\n\n<p>- Поддержка технологии VR (виртуальная реальность).</p>\n\n<p>- Легкая вставка готового виртуального тура на любой сайт и в социальные сети.</p>\n\n<p>- Поддержка сертификатов SSL (более защищенное соединение с сайтом).</p>\n\n<p>&nbsp;</p>\n\n<p style=\"text-align:center\"><strong>Принцип работы виртуального тура Google</strong></p>\n\n<p>&nbsp;</p>\n\n<p style=\"text-align:center\"><iframe frameborder=\"0\" height=\"480\" src=\"//vk.com/video_ext.php?oid=355457237&amp;id=456239021&amp;hash=cf7a80f4a88751de&amp;hd=2\" width=\"853\"></iframe></p>\n\n<p style=\"text-align:center\"><br />\n&nbsp;</p>\n', '2018-01-19 21:00:00', '2022-01-12 16:10:02', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(10, 'Виртуальный 3D-тур в Яндекс', '', 'Мы - официальный партнер Яндекса. Это позволит всем нашим клиентам разместить виртуальный тур на сервисах Яндекс. Панорамы компаний отображаются в карточках организаций на сервисах Яндекса.', NULL, 'Виртуальный 3D-тур в Яндекс', 'virtualnyiy-tur-v-yandeks', 'Пример размещения виртуального тура в Яндекс', '<p>Хорошая новость! Теперь<strong> мы - официальный партнер Яндекса</strong>.</p>\n\n<p>Это позволит всем нашим клиентам разместить виртуальный тур еще и в информационных ресурсах <strong>Яндекса: Поиск, Карты, Панорамы</strong>.</p>\n\n<p>&nbsp;</p>\n\n<p>Что это дает Вашему бизнесу?</p>\n\n<p>- <strong>20 млн. потенциальных клиентов в месяц</strong> могут&nbsp;увидеть Ваш виртуальный тур!</p>\n\n<p>- <strong>41% клиентов</strong>, изучив Вашу компанию на картах<strong> придут к Вам!</strong></p>\n\n<p>- Ваш <strong>интерьер будет доступен с мельчайших деталях!</strong></p>\n\n<p>- <strong>Клиенты легко найдут Вас</strong>, так как каждый виртуальный тур имеет вид с улицы!</p>\n\n<p>- Виртуальный тур это показатель открытости Вашего бизнеса!</p>\n\n<p>&nbsp;</p>\n\n<h2 style=\"text-align:center\">Больше, чем просто точка на карте</h2>\n\n<p>Панорамы компаний отображаются в&nbsp;карточках организаций в&nbsp;сервисах Яндекса.</p>\n\n<p>Карточка вашей организации на&nbsp;Яндекс.Картах&nbsp;&mdash; это не&nbsp;просто адрес. В&nbsp;ней пользователи могут найти всю необходимую информацию: часы работы, наличие Wi&shy;-Fi и&nbsp;прочие детали, а&nbsp;так&nbsp;же увидеть вашу компанию изнутри с&nbsp;помощью фотографий и&nbsp;панорам.</p>\n\n<p style=\"text-align:center\"><img alt=\"\" src=\"\\public\\images\\yandex_primer.jpg\" style=\"height:30%; width:100%\" /></p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p>Разместив виртуальный тур в Яндексе, Вы сможете легко вставить его на свой сайт, указав&nbsp;любой удобный размер&nbsp;окна для отображения 3D-тура.</p>\n\n<p>&nbsp;</p>\n\n<p style=\"text-align:center\"><strong>Пример вставки на сайт&nbsp;виртуального тура Яндекс:</strong></p>\n\n<div style=\"overflow:hidden; position:relative\"><a href=\"https://yandex.ru/maps/org/dommer/1031105547/?utm_medium=mapframe&amp;utm_source=maps\" style=\"color:#eee;font-size:12px;position:absolute;top:0px;\">Dommer</a><a href=\"https://yandex.ru/maps/62/krasnoyarsk/category/shopping_mall/184108083/?utm_medium=mapframe&amp;utm_source=maps\" style=\"color:#eee;font-size:12px;position:absolute;top:14px;\">Торговый центр в Красноярске</a><iframe frameborder=\"0\" height=\"550\" src=\"https://yandex.ru/map-widget/v1/-/CCUy6-ARWD\" style=\"position:relative;\" width=\"100%\"></iframe></div>\n\n<p>&nbsp;</p>\n', '2018-02-24 21:00:00', '2022-01-12 16:07:06', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(12, 'Бизнес по-русски или про некачественные 3D-туры', 'Бизнес по-русски или про некачественные 3D-туры', 'Бизнес по-русски или про некачественные 3D-туры', NULL, 'Бизнес по-русски или про некачественные 3D-туры', 'biznes-po-russki-ili-pro-nekachestvennyie-3d-turyi', 'Сегодня хочу поднять тему недобросовестных горе-исполнителей, которые формируют у аудитории негативные впечатления от виртуальных туров.', '<p style=\"text-align:justify\">&nbsp; &nbsp;Сегодня хочу поднять тему недобросовестных горе-исполнителей, которые формируют у аудитории негативные впечатления от виртуальных туров.<br />\n&nbsp; &nbsp;Достаточно популярно в наше время, купив любую фотоаппаратуру, громко кричать и предлагать услуги фотографа.<br />\n<br />\n&nbsp; &nbsp;Так и в сфере создания виртуальных туров. Купив простое оборудование или камеру 360&deg;, не имея опыта использования специальных программ, сразу бежать и предлагать коммерческие съемки, не заботясь о качестве готового продукта. А клиенты, зачастую не зная всех нюансов, соглашаются на такие услуги.<br />\n&nbsp; &nbsp;В итоге мы имеем множество примеров, где виртуальный тур получился, мягко говоря, &quot;закосяченный&quot;. Но клиент уже заплатил деньги, и ему ничего не остается как принять услугу.</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\">Обратите внимание на приведенные ниже картинки:</p>\n\n<p style=\"text-align:justify\"><br />\n<img alt=\"\" src=\"/public_html/public/images/kosyak_011.jpg\" /><img alt=\"засечки в стыках\" src=\"/public/images/kosyak_011.jpg\" style=\"height:316px; width:400px\" /><br />\n1. Часто в готовых панорамах присутствуют грубые ошибки склейки панорам (как на первой картинке). Стык внизу окна и на стойке информации.</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\"><img alt=\"\" src=\"/public/images/kosyak_02.jpg\" style=\"height:324px; width:400px\" /><br />\n2. Многие не заморачиваются с ретушью пола под точкой съемки, а просто стягивают в кучу изображение (вторая картинка).</p>\n\n<p style=\"text-align:justify\"><br />\n<img alt=\"\" src=\"/public/images/kosyak_03.jpg\" style=\"height:236px; width:400px\" /><br />\n3. Кто-то не обращает внимание на следы грязи и пятен, а они сильно портят восприятие (третья картинка)</p>\n\n<p style=\"text-align:justify\"><br />\n<img alt=\"\" src=\"/public/images/kosyak_04.jpg\" style=\"height:374px; width:400px\" /><br />\n4. Я уже не говорю про фантомные изображения от двигающихся объектов как на 4 картинке.</p>\n\n<p style=\"text-align:justify\"><br />\n<img alt=\"\" src=\"/public/images/kosyak_05.jpg\" style=\"height:284px; width:400px\" /><br />\n5. Некоторые пытаются самостоятельно все снять своим смартфоном, что из этого выходит показано на 5 картинке.</p>\n\n<p style=\"text-align:justify\"><br />\n<img alt=\"\" src=\"/public/images/kosyak_07.jpg\" style=\"height:254px; width:400px\" /><br />\n6. А некоторые умельцы не уделяют внимания выравниванию вертикалей и горизонталей, из-за чего изображение получается кривое и заваленное на бок (картинка 6).<br />\n<br />\n&nbsp; &nbsp;И это далеко не полный список ошибок и недоработок. Сюда же можно отнести отсутствие свето- и цвето-коррекции, резкости, детализации, &quot;вкусности&quot; изображения.<br />\n&nbsp; &nbsp;Просматривать такие &quot;веселые картинки&quot; не комфортно и они вряд ли принесут владельцу бизнеса желаемый эффект. Уж никак не покажут его презентабельно и выгодно, а наоборот, сформируют мнение &quot;тяп-ляп конторы&quot;.<br />\n<br />\n&nbsp; &nbsp;Мы же в своих работах уделяем всему этому большое внимание. Результаты нашей работы можно увидеть на нашем сайте.<br />\n<br />\n&nbsp; &nbsp;Да, возможно, у горе-исполнителей получается дешевле, за счет проигрыша в качестве, но это не наш метод. К слову, наши цены так же весьма демократичны. Об этом можно спросить у наших довольных клиентов, которые всегда помимо готовой работы получают еще различные &quot;пряники&quot; в виде дополнительных панорам, обработки, размещения 3D-тура не только в Google, но и в Яндексе, в социальных сетях и на своем сайте. Дополнительных вставок в тур мультимедийного контента (фото, видео, текста, кнопок, описаний...).<br />\n&nbsp; &nbsp;А в число наших клиентов-партнеров входят как представители мелкого бизнеса, так и большие федеральные и муниципальные заказчики.<br />\n<br />\n&nbsp; &nbsp;Мы всегда идем навстречу нашему клиенту-партнеру!&nbsp;<br />\n<br />\n&nbsp; &nbsp;Итак, если Вам нужен действительно качественный виртуальный тур, который не стыдно будет показать всем, то обращайте внимание на портфолио Исполнителя!<br />\n<br />\n&nbsp; &nbsp;Теперь Вы знаете у кого заказать виртуальный 3D-тур в Красноярске и Красноярском крае.</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\">&nbsp; &nbsp;Компания 3Dtur24 - официальный партнер Яндекс по размещению панорам на Яндекс-картах. А это говорит о высоких стандартах качества, которые недоступны многим &quot;создателям виртуальных туров&quot;.<br />\n<br />\n&nbsp; &nbsp;Заказать создание качественного 3D-тура:&nbsp;+7-913-585-41-57</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n', '2019-02-28 21:00:00', '2019-03-03 16:59:08', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(13, 'Google Trusted Verifier - Подтверждение Вашего бизнеса на картах Google', 'Google Trusted Verifier  Подтверждение Вашего бизнеса на картах Google', 'Google Trusted Verifier - Подтверждение Вашего бизнеса на картах Google', NULL, 'Google Trusted Verifier - Подтверждение Вашего бизнеса на картах Google', 'gmb_gtv', 'Статус доверенного представителя Google для подтверждения Вашего бизнеса в сервисе \"Google Мой бизнес\"', '<p style=\"text-align:justify\"><img alt=\"\" src=\"/public/images/gmb_tv.png\" style=\"border-style:solid; border-width:0px; float:left; height:86px; width:300px\" /></p>\n\n<p style=\"text-align:justify\">&nbsp; &nbsp;Месяц назад, после успешной сдачи тестов, Google подключил нас к программе мгновенного подтверждения бизнеса для сервиса &quot;Мой бизнес&quot;. Теперь<strong>&nbsp;</strong>у нас есть статус&nbsp;- доверенный представитель Google по подтверждению бизнеса -<strong> Google My Business Trusted Verifier</strong>.</p>\n\n<p style=\"text-align:justify\">&nbsp; &nbsp;Если Вы еще не зарегистрированы в бесплатном сервисе &quot;Google Мой бизнес&quot; - скорее туда! <a href=\"http://www.google.ru/business\">www.google.ru/business</a><br />\n&nbsp; &nbsp;С его помощью Вы сможете указать &nbsp;не только название компании и адрес, но так же рассказать о режиме работы в будни и праздники, разместить краткое описание своей компании, ознакомить потециальных клиентов с ключевыми позициями прайс-листа. Добавить фотографии, видео и даже виртуальный тур.</p>\n\n<p style=\"text-align:justify\">Для маркетологов там же присутствует раздел аналитики, показывающий поисковый трафик, количество запросов к сайту, звонки,...<br />\n&nbsp; &nbsp;Отдельно хочу отметить раздел работы с отзывами. Ведь сегодня любой желающий может оставить отзыв о Вашей компании в Google. И даже если он будет не очень хорошим, Вы всегда сможете на него отреагировать и написать ответ. Это Важная составляющая маркетинга, позволяющая осуществить обратную связь.</p>\n\n<p style=\"text-align:center\"><img alt=\"\" src=\"/public/images/gmb_screen.jpg\" style=\"height:388px; width:600px\" /></p>\n\n<p style=\"text-align:center\"><img alt=\"\" src=\"/public/images/gmb_screen_2.jpg\" style=\"height:303px; width:600px\" /></p>\n\n<p style=\"text-align:center\"><img alt=\"\" src=\"/public/images/gmb_screen_3.jpg\" style=\"height:234px; width:600px\" /></p>\n\n<p style=\"text-align:center\"><img alt=\"\" src=\"/public/images/gmb_screen_4.jpg\" style=\"height:235px; width:600px\" /></p>\n\n<p style=\"text-align:center\"><img alt=\"\" src=\"/public/images/gmb_screen_5.jpg\" style=\"height:224px; width:600px\" /></p>\n\n<p style=\"text-align:justify\">&nbsp; &nbsp;Для того, чтобы после заполнения всех необходимых данных Ваша компания появилась в поисковой выдаче, Вам необходимо подтвердить, что именно Вы являетесь владельцем (представителем владельца) бизнеса и Ваша компания расположена по указанному адресу. Если этого не сделать, то данные не публикуются в Google.<br />\n&nbsp; &nbsp;Подтвердить можно несколькими способами: письмо с кодом по почте России (которое обычно не доходит до адресата), звонок на телефонный номер компании (не всегда доступный метод) и мгновенное подтверждение бизнеса<strong> уполномоченным представителем Google</strong>. Как раз такой статус мы и получили.</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\">Теперь <strong>Вам не нужно долго ждать!&nbsp;</strong>Просто сделайте нам заявку любым способом. Наш сотрудник приедет к Вам в офис/магазин/шоу-рум&nbsp;(по месту ведения бизнеса), и с помощью специальной программы поможет Вам заполнить профиль компании и тут же мгновенно подтвердит его.</p>\n\n<p style=\"text-align:center\"><img alt=\"\" src=\"/public/images/gtvapp2.jpg\" style=\"height:294px; width:400px\" /></p>\n\n<p style=\"text-align:justify\">&nbsp; &nbsp;После всех процедур, в течении суток Ваша компания появится в поисковой выдаче у клиентов, которые в указанном районе ищут подобные компании.</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\">Будьте ближе к своим клиентам! Будьте лучше конкурентов!</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n', '2019-05-02 21:00:00', '2019-05-03 18:20:34', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(14, 'Виртуальный тур в Яндекс', 'Виртуальный тур в Яндекс панорамы интерьеров', '', NULL, 'Мы - партнеры Яндекса', 'partner-yandeksa', 'Размещение панорам интерьеров и виртуальных туров в Яндексе', '<p><img alt=\"\" src=\"/public/images/ya_logo.jpg\" style=\"height:68px; width:224px\" />Мы - официальные партнеры Яндекса по размещению панорам и виртуальных туров.</p>\n\n<p>Это значит, что заказав у нас панорамную съемку Ваших интерьеров, экстерьеров или фасадов&nbsp;Вы можете быть уверены в качестве предоставляемых услуг.</p>\n\n<p>&nbsp;</p>\n\n<p>Зачем нужен 3D тур в Яндексе?</p>\n\n<p>Таким способом Вы даете возможность Вашему потенциальному клиенту виртуально посетить Вашу компанию: посмотреть интерьеры отеля или ресторана, разглядеть оборудование клиники, увидеть своими глазами детали дизайна помещения, показать инженерные решения спроектированных удаленных объектов без реального посещения объекта. Перечислять различные преимущества можно долго.</p>\n\n<p>&nbsp;</p>\n\n<p>Панорамы интерьеров объединенные в&nbsp;готовый виртуальный тур формируют интерес клиента, демонстрируют открытость Вашего бизнеса, создают ценность бренда и&nbsp;работают на вас в режиме 24/7.</p>\n\n<p>&nbsp;</p>\n\n<p>На картинке ниже - фрагмент официальной справки Яндекса с описанием панорам интерьеров и нашими там контактами - звоните, всё расскажем и проконсультируем.</p>\n\n<p><img alt=\"\" src=\"/public/images/ya_info_contakts.jpg\" style=\"height:462px; width:950px\" /></p>\n\n<p>&nbsp;</p>\n\n<p>Пример размещения виртуального тура в Яндекс-картах (вращайте изображение мышкой и переходите по стрелкам-указателям между панорамами):</p>\n\n<div style=\"overflow:hidden; position:relative\"><a href=\"https://yandex.ru/maps/org/autodom/90948766429/?utm_medium=mapframe&amp;utm_source=maps\" style=\"color:#eee;font-size:12px;position:absolute;top:0px;\">AUTODOM</a><a href=\"https://yandex.ru/maps/11309/krasnoyarsk-krai/category/car_dealership/?utm_medium=mapframe&amp;utm_source=maps\" style=\"color:#eee;font-size:12px;position:absolute;top:14px;\">Автосалон в Красноярском крае</a><iframe frameborder=\"0\" height=\"550\" src=\"https://yandex.ru/map-widget/v1/-/CCQ3jGTjPD\" style=\"position:relative;\" width=\"100%\"></iframe></div>\n', '2020-10-06 21:00:00', '2022-01-12 16:12:40', 2, 1, 1);
INSERT INTO `articles` (`id`, `title`, `keywords`, `description`, `dir`, `name`, `translit`, `caption`, `text`, `date`, `date_update`, `user_id`, `sort`, `status`) VALUES(15, 'Интерьерная фотосъемка', 'Интерьерная фотосъемка', '', NULL, 'Интерьерная фотосъемка', 'interernaya-fotosyemka', 'Наша новая услуга - Интерьерная фотосъемка для бизнеса и личных задач.\nСнимаем интерьеры для аренды, продажи, для контента, для сайта, для социальных сетей.\nФотографии фасадов, оборудования, технологических процессов.\nЧитайте подробнее в нашей новой статье.', 'Рады предложить Вам еще одну нашу услугу - интерьерная фотосъемка для различных целей.\n<p> </p>\n\nВам нужно показать интерьер Вашего бизнеса?<br>\nКафе, рестораны, клиники, магазины, спортивные объекты, общественные пространства,... для любого вида бизнеса необходимо своевременно и на постоянной основе дополнять фото-контент в интернет-справочниках, на сайт, в социальные сети.\nМы готовы предоставить Вам качественные услуги по фотосъемке Ваших интерьеров.\n<p> </p>\nСдаете или продаете квартиру?<br>\nВам просто необходимо показать ее с помощью качественных фотографий!\nДа, можно снять самому на свой телефон и быстро выложить все в сети, но согласитесь, качественные фотографии привлекают намного больше и дают Вам большое преимущество на этапе первого знакомства потенциального покупателя/арендатора.\nБолее того, съемка жилых помещений для продажи и для аренды имеет в основе разные подходы. Например, чтобы показать квартиру в объявлении для аренды, достаточно обычно снять несколько ракурсов из углов комнаты на широкий угол, добавить пару деталей и всё. А для съемки квартиры на продажу необходимо показать не только угловые ракурсы, но и геометрически правильные кадры, которые формируют у покупателя правильное восприятие пространства.\n<p> </p>\nЕсли же мы будем говорить про фотосъемку помещений с целью демонстрации интерьера как результата дизайнерского ремонта или планирования, то тут на первый план выходит правильная геометрия, корректная цветопередачи и детали.\n<p> </p>\nЕще один классический пример - съемка интерьеров медицинской клиники.<br>\nКак Вы думаете, что работает лучше? Фотографии, снятые на смартфон, показывающие темные кабинеты и коридоры или же светлые, яркие фотографии с правильным балансом белого пусть и небольших кабинетов с оборудованием, которое выглядит новым?\nДумаю ответ тут очевиден. Любой человек выберет светлые фотографии с четкими видами аккуратных кабинетов и оборудования. А это уже лояльность клиента, которая может формироваться сразу на этапе первого знакомства с клиникой посредствам просмотра фотографий.\n<p> </p>\nА еще фотографии фасадов, входных групп, оборудования, технологических процессов.\nКаждый из этих пунктов также подразумевает свой подход к съемке для получения правильного результата.\n<p> </p>\nИ мы Вам в этом можем помочь!\n<p> </p>\nПосмотреть примеры наших фотосъемок для различных целей Вы можете по ссылке: <a href=\"https://cloud.mail.ru/public/R9Jz/pUVZkDWdx\" target=\"_blank\">Интерьерная фотосъемка</a>\n\n\n', '2025-11-19 21:00:00', '2025-11-21 18:15:29', 2, 1, 1);
