INSERT INTO `pages` (`id`, `parent`, `name`, `name_menu`, `translit`, `title`, `description`, `keywords`, `tizer`, `text`, `seo`, `date`, `date_update`, `user_id`, `sort`, `status`, `in_menu`, `in_route`) VALUES(9, NULL, 'Главная', 'Главная', '', 'Создание виртуальных туров и панорам 360° в Красноярске', 'У нас вы можете заказать создание качественного виртуального 3D тура. Мы размещаем наших клиентов на сервисах Яндекс карты. Панорамы компаний отображаются в карточках организаций во всех сервисах Яндекса. Мы можем разместить Ваш виртуальный тур в сервисах Google карты и просмотр улиц (панорамы). У нас огромный опыт создания виртуальных туров и приемлемая цена.', 'виртуальный тур, красноярск, панорама 360, 3D, 3Д, 3D-тур, заказать, создать, цена, сколько, стоит', '', '<p>Текст</p>\n', 'У нас вы можете заказать создание качественного виртуального 3D тура. Мы размещаем наших клиентов на сервисах Яндекс карты. Панорамы компаний отображаются в карточках организаций во всех сервисах Яндекса. Мы можем разместить Ваш виртуальный тур в сервисах Google карты и просмотр улиц (панорамы). У нас огромный опыт создания виртуальных туров и приемлемая цена.', '2013-07-29 14:11:59', '2019-04-07 00:04:44', 2, 0, 1, 1, 0);
INSERT INTO `pages` (`id`, `parent`, `name`, `name_menu`, `translit`, `title`, `description`, `keywords`, `tizer`, `text`, `seo`, `date`, `date_update`, `user_id`, `sort`, `status`, `in_menu`, `in_route`) VALUES(19, NULL, 'Портфолио', 'Портфолио', 'works', '', 'Ознакомьтесь с примерами наших работ. Заказывайте создание виртуальных туров с помощью формы заказа', '', '', '<p>Портфолио</p>\n', '', '2013-10-06 15:04:28', '2018-10-31 12:10:40', 2, 1, 1, 1, 0);
INSERT INTO `pages` (`id`, `parent`, `name`, `name_menu`, `translit`, `title`, `description`, `keywords`, `tizer`, `text`, `seo`, `date`, `date_update`, `user_id`, `sort`, `status`, `in_menu`, `in_route`) VALUES(25, NULL, 'Статьи', 'Статьи', 'articles', 'Статьи о виртуальных турах', 'Не знаете какие преимущества даёт вам виртуальный тур? Или не знаете о всех возможностях виртуального тура? Почитайте наши статьи о преимуществах и доступных технологиях виртуального тура. О плюсах рекламирования вашего бизнеса через виртуальный тур. Мы прошли сертификацию в Google по программе Google Street View. Мы - официальный партнер Яндекса.', 'статьи, виртуальный тур, красноясрк, панорама 360', '', '', '', '2015-10-05 09:02:50', '2018-10-31 12:10:04', NULL, 2, 1, 1, 0);
INSERT INTO `pages` (`id`, `parent`, `name`, `name_menu`, `translit`, `title`, `description`, `keywords`, `tizer`, `text`, `seo`, `date`, `date_update`, `user_id`, `sort`, `status`, `in_menu`, `in_route`) VALUES(26, NULL, 'Цены', 'Цены', 'price', 'Цены на 3d туры', 'Узнать цены на 3d туры', 'price цены стоимость условия ', '', '<p>&nbsp;</p>\n\n<p><strong>Если кратко</strong>, то минимальная стоимость готового виртуального тура &quot;под ключ&quot; - <strong>от 5000 рублей</strong>.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Подробнее:</strong></p>\n\n<p>Итоговая стоимость каждого виртуального 3D тура зависит от количества точек съемки (панорам 360 градусов) и количества дополнительных материалов, интегрированных в тур (фотографий, текста, видеороликов, картинок, описаний).</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Важно!</strong></p>\n\n<p>Все работы оплачиваются разово/единовременно.&nbsp;Размещение панорам и виртуальных туров в Яндексе и в Google дополнительно не оплачивается. Абонентской платы тоже нет.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Виртуальный тур (панорамы 360&deg;) для размещения в Яндексе&nbsp;</strong><a href=\"https://www.3dtur24.ru/articles/item/virtualnyiy-tur-v-yandeks.html\" target=\"_blank\">Пример</a><strong> + Google&nbsp;</strong> <a href=\"https://www.3dtur24.ru/articles/item/virtualnyiy-3d-tur-google.html\" target=\"_blank\">Пример</a></p>\n\n<p>Пакет &quot;Минимальный&quot; - 2 панорамы (вид с улицы + внутри) - 5000 рублей.</p>\n\n<p>Пакет &quot;Малый бизнес&quot; - 3 панорамы (улица, интерьер 1, интерьер 2) - 6000 рублей.</p>\n\n<p>Пакет &quot;Стандарт&quot; - 5 панорам - 10000 рублей.</p>\n\n<p>Пакет &quot;Корпоративный&quot; - 10 панорам -19000 рублей.</p>\n\n<p>Пакет &quot;Максимальный&quot; - количество панорам неограничено, стоимость обсуждается индивидуально.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Виртуальный тур с индивидуальным дизайном (для размещения на сайте Заказчика,&nbsp;а так же&nbsp;в соц.сетях). </strong><a href=\"https://www.3dtur24.ru/panorama/metagi02/index.html\">Пример</a><strong> </strong></p>\n\n<p>Количество&nbsp;панорам в туре:</p>\n\n<p>до 10: стоимость 1 панорамы - 2000 рублей.</p>\n\n<p>от 10 и более: стоимость 1 панорамы - 1900 рублей.</p>\n\n<p><strong>Дополнительные материалы:</strong></p>\n\n<p>Вставка в виртуальный тур панели навигации с кнопками управления - 2000 руб.</p>\n\n<p>Вставка фотографии - 300 руб.</p>\n\n<p>Вставка текста - 300 руб.</p>\n\n<p>Вставка видеоролика - 500 руб.</p>\n\n<p>Вставка логотипа заказчика в надир (под ноги) - 400 руб.</p>\n\n<p>Ретушь отражения в зеркале - 500 руб.</p>\n\n<p>Вставка дополнительной кнопки с описанием панорамы - 500 руб.</p>\n\n<p>Карта виртуального тура - от 1000 руб.</p>\n\n<p>Вставка готового тура на сайт заказчика - от 2000 руб.</p>\n\n<p>Размещение готового виртуального тура в соц.сети - 2000 руб.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Предметное фото 360&deg;</strong> <a href=\"https://www.3dtur24.ru/panorama/svetofor/index.html\">Пример</a></p>\n\n<p>Стоимость одного предмета размером до 20х20х20 см с вращением вокруг своей оси - 2500 рублей.</p>\n\n<p>При большем количестве предметов - цена определяется индивидуально и зависит от размеров&nbsp;объекта, геометрической сложности и&nbsp;количества кадров, необходимых для построения анимированного изображения.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Аэропанорамы с квадрокоптера </strong><a href=\"https://www.3dtur24.ru/panorama/aero/index.html\">Пример</a></p>\n\n<p>1 панорама - 4000 рублей</p>\n\n<p>Минимальный заказ - 3 панорамы.</p>\n\n<p>При количестве панорам свыше 5 - индивидуальные условия.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Фото-&nbsp;видео- съемка с квадрокоптера</strong></p>\n\n<p>Индивидуальые условия.</p>\n\n<p>Минимальное время полета - 20 минут.</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Интерьерная фотосъемка </strong><a href=\"https://cloud.mail.ru/public/R9Jz/pUVZkDWdx\" target=\"_blank\">Примеры</a></p>\n\n<p>1 час съемки - 4000 рублей</p>\n\n<p>Комплект из 15-20 фотографий с ретушью и обработкой.</p>\n\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n\n<p><strong>Ознакомились с ценами и хотите бонус?</strong></p>\n\n<p>Позвоните нам по номеру: +7-913-585-41-57 или заполните заявку, используя форму &quot;Заказать звонок&quot;</p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Важно!</strong></p>\n\n<p>Итоговая стоимость Вашего заказа может отличаться от указанных цен!</p>\n\n<p>&nbsp;</p>\n\n<p>Представленные цены носят исключительно ознакомительный характер и не являются договором-офертой!</p>\n\n<p>&nbsp;</p>\n\n<p style=\"text-align:center\"><img alt=\"сертификат Google\" src=\"http://www.3dtur24.ru/public/images/gsv.jpg\" style=\"height:140px; width:130px\" />&nbsp; &nbsp; &nbsp;&nbsp;<img alt=\"\" src=\"http://www.3dtur24.ru/public/images/yandex_partner2.png\" style=\"height:140px; width:143px\" /></p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p style=\"text-align:center\"><a href=\"http://www.3dtur24.ru/public/images/check_list.pdf\"><img alt=\"Чек лист для подготовки помещения к съемке виртуального тура\" src=\"/public/images/check_list_icon.jpg\" style=\"height:100px; width:100px\" /></a></p>\n\n<p style=\"text-align:center\">Чек лист по подготовке помещения к съемке виртуального тура</p>\n', 'Узнать цены на 3d туры\nprice\nцены\nстоимость\nусловия \nзаказать виртуальный тур\nкупить виртуальный тур\nсоздать виртуальный тур\nсделать 3Д тур\nпанорама 360\nсферическая панорама\nкруговая панорама\nGoogle панорама\nЯндекс панорама\nвиртуальный тур в Красноярске', '2017-01-12 11:15:51', '2025-11-21 16:11:27', NULL, 0, 1, 1, 1);
INSERT INTO `pages` (`id`, `parent`, `name`, `name_menu`, `translit`, `title`, `description`, `keywords`, `tizer`, `text`, `seo`, `date`, `date_update`, `user_id`, `sort`, `status`, `in_menu`, `in_route`) VALUES(27, NULL, 'Контакты', 'Контакты', 'contakts', 'Контакты', 'Наш адрес: г. Красноярск, ул.Линейная д. 89, офис 3-02 тел: +7-913-585-41-57 E-mail: 3dtur24@mail.ru', 'контакты, телефон, почта, банковские реквизиты, ссылка на социальные сети, альтиус, 3dtur24', '', '<p><strong>Индивидуальный предприниматель Лапицкий Павел Владимирович</strong></p>\n\n<p>&nbsp;</p>\n\n<p><span style=\"font-size:10.0pt\"><span style=\"color:black\"><strong>ИНН</strong> 246308434267&nbsp;&nbsp; <strong>ОГРНИП</strong> 322246800091071</span></span></p>\n\n<p><br />\n<strong>тел: +7-913-585-41-57</strong></p>\n\n<p><br />\n<strong>E-mail:</strong> <a href=\"mailto:3dtur24@mail.ru?subject=%D0%A1%D0%BE%D0%BE%D0%B1%D1%89%D0%B5%D0%BD%D0%B8%D0%B5%20%D1%81%20%D1%81%D0%B0%D0%B9%D1%82%D0%B0%203dtur24.ru\">3dtur24@mail.ru</a></p>\n\n<p>&nbsp;</p>\n\n<p><strong>Наш адрес:</strong> г. Красноярск, ул.Линейная д. 89, офис 3-02</p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Наш Instagram:</strong>&nbsp;<a href=\"http://www.instagram.com/3dtur24/\">www.instagram.com/3dtur24/</a></p>\n\n<p><strong>Группа в Facebook:</strong>&nbsp;<a href=\"http://www.facebook.com/3dtur24/\">www.facebook.com/3dtur24/</a></p>\n\n<p><strong>Группа ВКонтакте:</strong>&nbsp;<a href=\"http://vk.com/3dtur24\">vk.com/3dtur24</a></p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Время работы:</strong></p>\n\n<p>Пн.-Пт.: 10:00-18:00</p>\n\n<p>Сб., Вс.: Выходной</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Банковские реквизиты:</strong></p>\n\n<p>Р/с: 40802810723590002614</p>\n\n<p>Филиал &quot;Новосибирский&quot; АО &quot;АЛЬФА-БАНК&quot;</p>\n\n<p>БИК: 045004774</p>\n\n<p>Кор/с: 30101810600000000774</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Схема проезда:</strong></p>\n\n<p><iframe frameborder=\"0\" height=\"400\" src=\"https://yandex.ru/map-widget/v1/?z=12&amp;ol=biz&amp;oid=216989416152\" width=\"560\"></iframe></p>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n\n<p><strong>Яндекс рейтинг компании:</strong></p>\n\n<iframe src=\"https://yandex.ru/sprav/widget/rating-badge/216989416152?type=rating\" width=\"150\" height=\"50\" frameborder=\"0\"></iframe>\n\n<p>&nbsp;</p>\n\n<p>&nbsp;</p>\n', 'Контактная информация\nИП Лапицкий Павел Владимирович 3dtur24\nвиртуальные туры и панорамы 360\nКрасноярск, край, Хакасия', '2017-01-12 11:15:51', '2024-01-09 10:01:08', NULL, 0, 1, 1, 1);
