INSERT INTO `page_history` (`id`, `page_id`, `changed_by_user_id`, `action`, `date_update`, `name`, `name_menu`, `translit`, `title`, `description`, `keywords`, `tizer`, `text`, `seo`, `date`, `page_user_id`, `sort`, `status`, `in_menu`) VALUES(11, 3, 2, 'delete', '2013-08-20 10:41:33', 'О нас и в глаз', 'О нас и в глаз', 'o-nas-i-v-glaz', 'О нас и в глаз', 'О нас и в глаз', 'О нас и в глаз', '', '', '', '2013-06-25 14:05:50', 2, 0, 1, 1);
INSERT INTO `page_history` (`id`, `page_id`, `changed_by_user_id`, `action`, `date_update`, `name`, `name_menu`, `translit`, `title`, `description`, `keywords`, `tizer`, `text`, `seo`, `date`, `page_user_id`, `sort`, `status`, `in_menu`) VALUES(12, 18, 2, 'change_status', '2013-09-09 16:07:03', 'Внимание!!! У Вас есть уникальный шанс заказать сайт бесплатно!', 'Акция', 'action', '', '', '', '', '<p>Да, вы не ослышались, мы действительно готовы разработать сайт бесплатно. Акция действует только для 3-х первых клиентов, поэтому нажимайте <strong><a onclick=\"popupFx.show();\">заказать сайт</a> прямо сейчас</strong>, и станьте одним из 3 счастливчиков!</p>\n<p>&nbsp;</p>\n<h3>Условия акции просты:</h3>\n<ul>\n<li>Вам надо <a onclick=\"popupFx.show();\">сделать заказ</a> прямо сейчас, чтобы успеть попасть в тройку первых</li>\n<li>Обязательно заказать дизайн сайта у нас</li>\n</ul>\n<h3>Наверняка хотите знать, как запусть сайт с минимальными вложениями?</h3>\n<p>Всем известно, что хороший сайт стоит дорого (сайт-визитка от 30 тысяч, интернет-магазин от 60-80 тысяч) и делают их крупные компании такие как: <a href=\"http://www.metadesign.ru/\" target=\"_blank\" title=\"Метадизайн\">Метадизайн</a>, <a href=\"http://krasinsite.ru/\" target=\"_blank\" title=\"КрасИнсайт\">КрасИнсайт</a>, <a href=\"http://weltgroup.ru/\" target=\"_blank\" title=\"Weltgroup\">wwweltgroup</a> и т.д.<br />Но не каждый начинающий предприниматель может себе это позволить.<br />Есть 2 пути решения этой проблемы:<br /><strong>&nbsp;</strong></p>\n<div style=\"padding-left: 10px;\">\n<p><cite><strong>1. Создать сайт самому.</strong> Сегодня есть много бесплатных систем управления сайта(wordpress, joomla, MODx, и т.д.)<br />Плюсы:</cite></p>\n<ul>\n<li><cite>Бесплатно</cite></li>\n<li><cite>Получите новый навык</cite></li>\n<li><cite>Не зависите от web-студии</cite></li>\n</ul>\n<p><cite>Минусы:</cite></p>\n<ul>\n<li><cite>Долго</cite></li>\n<li><cite>Нет гарантии что у Вас получится</cite></li>\n<li><cite>Нет гарантии качества</cite></li>\n<li><cite>Трата личного времени</cite></li>\n</ul>\n<p><cite><strong>2. Заказать недорогой сайт в web-студии.</strong> Очень много студентов, начинающих компаний, готовых сделать Вам сайт за символическую сумму.<br />Плюсы:</cite></p>\n<ul>\n<li><cite>Дешево</cite></li>\n<li><cite>Не тратите личное время</cite></li>\n<li><cite>Все вопросы решают разработчики</cite></li>\n<li><cite>Возможно вам повезет и попадутся толковые разработчики</cite></li>\n</ul>\n<p><cite>Минусы:</cite></p>\n<ul>\n<li><cite>Нет гарантии в качестве продукта</cite></li>\n<li><cite>Большинство дешевых сайтов неудобны в управлении</cite></li>\n<li><cite>В 50% случаев, после разработки сайта вспоминается поговорка \"Скупой платит дважды\"</cite></li>\n</ul>\n</div>\n<p><strong>Но, мы предлагаем 3-й вариант - <a onclick=\"popupFx.show();\">бесплатная разработка!</a></strong></p>\n<h3>Почему мы готовы сделать Вам сайт бесплатно?</h3>\n<p>Все знают закон сева и жатвы -&nbsp;<span>&laquo;Что посеешь, то и пожнешь<span>&raquo;. Это значит, что Вы получаете то, что посеяли в прошлом. Ваша сегодняшняя жизнь является результатом прежних поступков и принятых решений. </span></span></p>\n<p><span><span>Так вот, мы готовы помочь Вам в развитии вашего бизнеса, и возможно, вы захотите продолжить с нами работу или поможете нам в той области, в которой вы являетесь профессионалами.</span></span></p>\n<p><span><span><span>Главная задача - думать о&nbsp;</span><span>том, как принести пользу человеку,&nbsp;</span><span>а только потом уже действовать&nbsp;</span><span>в своих интересах.&nbsp;</span>К сожалению мы не можем оказать такую услугу всем, поэтому чтобы успеть, делайте заказ <strong><a onclick=\"popupFx.show();\">прямо сейчас!</a></strong></span></span></p>\n<h3>Почему нам можно доверять?</h3>\n<p>Во-первых, мы любим свою работу!</p>\n<p>У нашей команды за плечами большой опыт web-разработки. Многие сотрудники работали в крупных компаниях и им есть чем вас удивить.</p>\n<p>Ниже представлена таблица цен и сроков разработки сайтов Красноярска. Источник <a href=\"http://losin.ru/market-2012/\" target=\"_blank\">losin.ru</a></p>\n<p><img style=\"vertical-align: middle; display: block; margin: 10px auto; border: 0px;\" src=\"http://webkuznya24.ru/public/media/losin.jpg\" border=\"0\" width=\"586\" height=\"720\" /></p>\n<p>Из таблицы видно, что самый дешевый интернет-магазин стоит от 50 тысяч!!! Так зачем упускать возможность получить сайт такого же качества БЕСПЛАТНО???</p>\n<h3>Бонус</h3>\n<p>При заказе Вы получаете бесплатное сопровождение на 2 месяца!</p>\n<p>&nbsp;</p>\n<p><strong>P.S. </strong>Напоминаем, акция действует только для первых 3-х клиентов.</p>\n<p>При заказе Вы оплачиваете только домен, хостинг и дизайн, если у Вас их нет.</p>\n<p>Остальное мы делаем БЕСПЛАТНО!!! + Вы полчаете сопровождение на 2 месяца!</p>\n<p>&nbsp;</p>\n<p>Поторопитесь <a onclick=\"popupFx.show();\">заказать сайт</a></p>\n<p>&nbsp;</p>\n<p>Удачи!</p>', '', '2013-08-30 10:33:16', 2, 3, 1, 1);
