INSERT INTO `settings` (`id`, `title`, `keywords`, `description`, `text_top`, `phone`, `email`, `text_bottom`) VALUES(1, 'Создание виртуальных туров и панорам 360&#176; в Красноярске и по всей Сибири', 'virtual tour panorama 360 google street view виртуальный тур панорама гугл стрит вью яндекс карты панорамы интерьеры заказать 3Д 3D ', 'Создание виртуальных туров и панорам 360&#176; в Красноярске и по всей Сибири', 'Создание виртуальных туров и панорам 360&#176; в Красноярске и по всей Сибири', '+7-913-585-41-57', '3dtur24@mail.ru', 'Создание виртуальных туров и панорам 360&#176; в Красноярске и по всей Сибири');
INSERT INTO `slides` (`id`, `h1`, `text1`, `img1`, `h2`, `text2`, `img2`, `h3`, `text3`, `img3`, `label_video`, `video`, `sort`, `status`) VALUES(1, 'Создание виртуальных туров и панорам 360° в Красноярске и по всей Сибири', '<p style=\"text-align:justify\">Мы занимаемся созданием панорамных фотографий для любого вида бизнеса, которые объединяются в единый виртуальный тур с дополнительными информационными материалами в виде текста, фотографий, видеороликов, позволяя заинтересовать клиента, погрузить его в атмосферу заведения и мотивировать посетить Ваше заведение, либо приобрести представленный у Вас товар/услугу.</p>\n\n<p style=\"text-align:justify\">Виртуальный тур состоит из сферических панорам &ndash; фотографий с охватом 360&deg;, которые связаны между собой специальными точками перехода.</p>\n\n<p style=\"text-align:justify\"><strong>Кому нужен виртуальный 3Д-тур?</strong>&nbsp;Любой пользователь/потенциальный клиент перед посещением заведения в первую очередь хочет соориентироваться на местности, понять где это находится. Вот тут как раз виртуальный тур&nbsp;дает полное представление о местоположении, так как привязан к картам и позволяет увидеть не только точку на карте, но и посмотреть панораму местности, чтобы увидеть знакомые ориентиры.<br />\nБолее того, клиент может легко в любое время не только с компьютера, но даже с любого мобильного устройства детально рассмотреть все интерьеры Вашего заведения, &quot;прогуляться&quot; виртуально и оценить все преимущества Вашего заведения/товаров, чтобы последующее посещение стало для него легким, комфортным и целенаправленным.</p>\n\n<p style=\"text-align:justify\"><strong>Виртуальный тур актуален&nbsp;для любых организаций:</strong> <a href=\"https://www.3dtur24.ru/panorama/skver/index.html\">кафе</a>, <a href=\"https://www.3dtur24.ru/panorama/terrasa/index.html\">ресторанов</a>,&nbsp;<a href=\"https://www.3dtur24.ru/panorama/museum/index.html\">музеев</a>, <a href=\"https://www.3dtur24.ru/panorama/ajur/index.html\">гостиниц</a>, <a href=\"https://www.3dtur24.ru/panorama/r29/index.html\">развлекательных центров</a>, <a href=\"https://www.3dtur24.ru/panorama/kss/index.html\">хостелов</a>, баз отдыха, <a href=\"https://www.3dtur24.ru/panorama/stomatologiya-jemchug/index.html\">медицинских клиник</a>, бань и саун, <a href=\"https://www.3dtur24.ru/panorama/atcmayak/index.html\">автосервисов</a>, <a href=\"https://www.3dtur24.ru/panorama/sportivnyiy-kompleks/index.html\">спортивных залов</a> и <a href=\"https://www.3dtur24.ru/panorama/fitnes3/index.html\">фитнес-центров</a>, <a href=\"https://www.3dtur24.ru/panorama/assortim/index.html\">магазинов</a>, <a href=\"https://www.3dtur24.ru/panorama/butik-baldinini/index.html\">бутиков</a>, <a href=\"https://www.3dtur24.ru/panorama/fitnes2/index.html\">тренажерных залов</a>, <a href=\"https://www.3dtur24.ru/panorama/ga/index.html\">объектов недвижимости</a>, <a href=\"https://www.3dtur24.ru/panorama/aero/index.html\">строительных площадок</a>, салонов красоты и просто парикмахерских, <a href=\"https://www.3dtur24.ru/panorama/ftk/index.html\">детских садиков</a>, <a href=\"https://www.3dtur24.ru/panorama/krkt/index.html\">образовательных центров</a>, ...</p>\n\n<p style=\"text-align:justify\">По данным исследований Google,&nbsp;страницы компаний с виртуальным туром привлекают внимание клиентов в 2 раза чаще, чем все остальные.</p>\n\n<p style=\"text-align:center\"><img alt=\"сертификат Google\" src=\"/public/images/gsv.jpg\" style=\"height:150px; width:139px\" />&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;<img alt=\"\" src=\"/public/images/yandex_partner2.png\" style=\"height:150px; width:153px\" />&nbsp;</p>\n\n<p style=\"text-align:justify\"><strong>Cтатус сертифицированных фотографов Google&nbsp;</strong>позволяет нам размещать Ваши виртуальные туры в поисковой системе Google, картах Google, сервисе Google.Просмотр улиц&nbsp;и в сервисе Google.Мой бизнес.</p>\n\n<p style=\"text-align:justify\">Более того, <strong>мы являемся официальными партнерами Яндекс</strong> и можем обновить уличные и разместить панорамы Ваших интерьеров во всех сервисах Яндекса.&nbsp;Это значит, что охват аудитории, которая увидит Ваш виртуальный тур значительно увеличивается, благодаря его доступности через сервисы Яндекс.Поиск, Яндекс.Справочник, Яндекс.Карты и Яндекс.Панорамы.</p>\n\n<p style=\"text-align:justify\"><a href=\"https://www.3dtur24.ru/articles/item/virtualnyiy-3d-tur-google.html\">Подробнее о виртуальных турах Google</a>&nbsp;<a href=\"https://www.3dtur24.ru/articles/item/virtualnyiy-3d-tur-google.html\"><img alt=\"\" src=\"/public/images/view_button.png\" style=\"height:25px; width:144px\" /></a></p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\"><a href=\"https://www.3dtur24.ru/articles/item/virtualnyiy-tur-v-yandeks.html\">Подробнее о виртуальных турах Яндекс</a>&nbsp;<a href=\"https://www.3dtur24.ru/articles/item/virtualnyiy-tur-v-yandeks.html\"><img alt=\"\" src=\"/public/images/view_button.png\" style=\"height:25px; width:144px\" /></a></p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\"><strong>Что дает виртуальный 3D-тур?</strong> Размещение виртуального 3D-тура (круговых панорам) Вашего бизнеса в сервисах Google и Яндекс позволяет вывести карточку Вашей компании в интернет-справочниках и Ваш сайт выше в поисковом рейтинге&nbsp;по-сравнению с конкурентами,&nbsp;тем самым получить приток клиентов и продвижение информации о Вашем бизнесе в интернете.</p>\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\"><strong>Помощь в создании и подтверждении карточек в &nbsp;Яндекс.Бизнес.&nbsp;</strong>Для отображения актуальной информации о Вашей компании во всех сервисах Яндекса Вам необходимо создать, заполнить контентом и подтвердить данные о Вашей компании. От того, насколько правильно и корректно указаны данные, напрямую зависит возможность идентификации бренда и охват аудитории. Мы помогаем Вам решать эти задачи, а в некоторых случаях берем это полностью на себя!</p>\n\n<p style=\"text-align:justify\">Это значит, что Ваши потенциальные клиенты&nbsp;при поиске подобных товаров (услуг)&nbsp;увидят Ваши контакты во всех сервисах Яндекса.\n\n<p style=\"text-align:justify\">&nbsp;</p>\n\n<p style=\"text-align:justify\">Опыт, накопленный за 10 лет, позволяет предоставить Вам полный спектр услуг, начиная от создания и подтверждения профиля компании в Яндексе и в Google, рекомендаций по их дальнейшему наполнению контентом, съемки виртуального тура с индивидуальным дизайном и размещением готового 3D тура как на Вашем сайте, так и во всех сервисах Яндекса и Google, в социальной сети ВКонтакте и в мессенджерах.</p>\n\n<p style=\"text-align:center\"><strong>Индивидуальный подход к каждому клиенту &ndash; наш ключ к успешной реализации проекта!</strong></p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n\n<p style=\"text-align:center\">Чек-лист по подготовке помещения к съемке виртуального тура</p>\n\n<p style=\"text-align:center\"><a href=\"/public/images/check_list.pdf\"><img alt=\"\" src=\"/public/images/check_list_icon.jpg\" style=\"height:100px; width:100px\" /></a></p>\n\n<p style=\"text-align:center\">&nbsp;</p>\n<!-- Global site tag (gtag.js) - Google Ads: 767900514 --><!-- Event snippet for Заказ тура conversion page -->', '180409162145.png', '', '', '180409162203.png', '', '', '210621182223.jpeg', 'Сюжет о нас в программе Новое утро на канале ТВК-Красноярск', '<iframe src=\"https://www.youtube.com/embed/ezLd6Uihe1E\" frameborder=\"0\" ></iframe>', 10, 1);
